async function orderForm(pr=null){const [suppliers,prs]=await Promise.all([refs('suppliers'),refs('purchase-requests')]);const sources=(pr?[pr]:prs).flatMap(p=>p.lines.filter(l=>Number(l.available_qty)>0).map(l=>({...l,request_no:p.request_no})));if(!sources.length){toast('没有可分配的已批准申请行，请先完成审批',true);return}const html=`<div class="notice">所有订单明细必须来自已批准申请。草稿订单也会占用申请可分配数量。</div><div class="form-grid">${select('supplier_id','供应商',options(suppliers),'',true,true)}</div><div class="form-section">订单明细<button type="button" id="add-line" class="button small">＋ 添加明细</button></div><div id="order-lines"></div>`;formOpen('创建采购订单',html,async(d,f,key)=>{d.lines=$$('.line-fields',f).map(el=>Object.fromEntries($$('input,select',el).map(e=>[e.name,e.value])));await api('purchase-orders','POST',d,key);await saved('订单草稿已创建，请在详情中确认')},'创建订单');const add=()=>addLine($('#order-lines'),select('request_line_id','已批准申请行',sources.map(l=>[l.id,`${l.request_no} · ${l.item_name} · 可分配 ${fmt(l.available_qty)}`]),'',true,true)+field('qty','采购数量','','number')+field('unit_price','采购单价（USD）','','number'));$('#add-line').onclick=add;add()}
async function receiptForm(po=null){const [orders,whs]=await Promise.all([refs('purchase-orders'),refs('warehouses')]);const candidates=po?[po]:orders.filter(o=>o.lines.some(l=>Number(l.remaining_qty)>0));if(!candidates.length){toast('暂无已确认且可收货的采购订单',true);return}let selected=candidates[0];const html=`<div class="notice">每次分批到货使用独立内部批次，单价沿用采购订单。保存后请在详情中确认过账。</div><div class="form-grid">${select('order_id','采购订单',options(candidates),selected.id,true,true)}</div><div class="form-section">收货明细<button type="button" id="add-line" class="button small">＋ 添加明细</button></div><div id="receipt-lines"></div>`;formOpen('登记分批收货',html,async(d,f,key)=>{d.lines=$$('.line-fields',f).map(el=>Object.fromEntries($$('input,select',el).map(e=>[e.name,e.value])));const r=await api('receipts','POST',d,key);toast('收货草稿已保存，尚未增加库存');await detail('receipts',r.data.id);await loadCurrentBehind()},'保存收货草稿');const add=()=>addLine($('#receipt-lines'),select('order_line_id','订单物料',selected.lines.filter(l=>Number(l.remaining_qty)>0).map(l=>[l.id,`${l.item_name} · 剩余 ${fmt(l.remaining_qty)} ${l.base_uom}`]),'',true,true)+select('warehouse_id','目标仓库',options(whs))+field('qty','实收数量','','number')+field('batch_no','内部批次号','')+field('supplier_lot','供应商批号','','text',false)+field('expires_on','有效期','','date',false));$('#add-line').onclick=add;$('[name=order_id]').onchange=e=>{selected=candidates.find(o=>o.id===e.target.value);$('#receipt-lines').innerHTML='';if(selected)add()};add()}
async function issueForm(){const [tasks,balances]=await Promise.all([refs('tasks'),refs('balances')]);const available=balances.filter(b=>Number(b.available_qty)>0).sort((a,b)=>(a.expires_on||'9999').localeCompare(b.expires_on||'9999'));if(!tasks.length||!available.length){toast(!tasks.length?'暂无可领料的进行中任务':'暂无未过期可领用库存',true);return}const html=`<div class="notice">批次按有效期从近到远推荐。需求草稿不预留库存，过账时重新检查余额与任务状态。</div><div class="form-grid">${select('task_id','领料任务',tasks.map(t=>[t.id,`${t.project_code} · ${t.title}`]),'',true,true)}${textarea('reason','领料说明','',false)}</div><div class="form-section">领料明细<button type="button" id="add-line" class="button small">＋ 添加物料</button></div><div id="issue-lines"></div>`;formOpen('创建项目领料需求',html,async(d,f,key)=>{d.lines=$$('.line-fields',f).map(el=>{const b=available.find(b=>b.id===$('[name=balance_id]',el).value);return {batch_id:b.batch_id,warehouse_id:b.warehouse_id,qty:$('[name=qty]',el).value}});const r=await api('stock/issues/drafts','POST',d,key);toast('领料需求已保存，等待库管过账');await detail('movements',r.data.id);await loadCurrentBehind()},'保存领料需求');const add=()=>addLine($('#issue-lines'),select('balance_id','物料 · 批次 · 仓库 · 余额',available.map(b=>[b.id,`${b.item_name} / ${b.batch_no} / ${b.warehouse_name} / ${fmt(b.available_qty)} ${b.base_uom} / 到期 ${b.expires_on||'无'}`]),'',true,true)+field('qty','领料数量','','number'));$('#add-line').onclick=add;add()}
async function transferForm(balance=null){const [bs,whs]=await Promise.all([refs('balances'),refs('warehouses')]);const available=balance?[balance]:bs;const html=`<div class="form-grid">${select('balance_id','来源批次 / 仓库',available.map(b=>[b.id,`${b.item_name} · ${b.batch_no} · ${b.warehouse_name} · 余额 ${fmt(b.on_hand_qty)}`]),balance?.id||'',true,true)}${select('to_warehouse_id','目标仓库',options(whs))}${field('qty','调拨数量','','number')}${textarea('reason','调拨说明')}</div>`;formOpen('仓库调拨',html,async(d,f,key)=>{const b=available.find(x=>x.id===d.balance_id);await api('stock/transfers','POST',{batch_id:b.batch_id,from_warehouse_id:b.warehouse_id,to_warehouse_id:d.to_warehouse_id,qty:d.qty,reason:d.reason},key);await saved('调拨已过账，两仓余额已同步更新')},'确认调拨')}
function adjustmentForm(b){const html=`<div class="notice">${esc(b.item_name)} · ${esc(b.batch_no)} · ${esc(b.warehouse_name)}<br>当前账面 ${fmt(b.on_hand_qty)} ${b.base_uom}。差额由系统根据读取时版本计算。</div><div class="form-grid">${field('count_qty','实际盘点数量',b.on_hand_qty,'number',true,true)}${textarea('reason','调整原因','',true)}</div>`;formOpen('库存盘点调整',html,async(d,f,key)=>{await api('stock/adjustments','POST',{...d,batch_id:b.batch_id,warehouse_id:b.warehouse_id,expected_version:b.version},key);await saved('盘点调整已过账')},'确认调整')}
async function openingForm(){const sys=(await api('system')).data;if(sys.opening_closed){toast('首次业务收货或领料后，期初录入入口已关闭');return}const [items,whs]=await Promise.all([refs('items'),refs('warehouses')]);formOpen('期初库存录入',`<div class="notice">仅业务启用前允许。必须使用没有历史流水的新批次。</div><div class="form-grid">${select('item_id','物料',options(items))}${select('warehouse_id','仓库',options(whs))}${field('batch_no','内部批次号')}${field('expires_on','有效期','','date',false)}${field('qty','数量','','number')}${field('unit_cost','单位成本（USD）','','number')}</div>`,async(d,f,key)=>{await api('stock/opening','POST',d,key);await saved('期初库存已过账')},'确认期初入库')}
async function membersForm(p){const people=await refs('people');const html=`<div class="notice">负责人必须是成员；移除成员前必须移交其未完成任务。</div><div class="form-grid">${select('user_id','用户',options(people),'',true,true)}${select('operation','成员操作',[['add','加入项目'],['remove','移出项目']],'add')}</div>`;formOpen('管理项目成员',html,async(d,f,key)=>{await api('projects/'+p.id+'/members','POST',{user_id:d.user_id,remove:d.operation==='remove',expected_version:p.version},key);await saved('项目成员已更新')})}
async function importForm(){const html=`<div class="notice">UTF-8 CSV · 最大 5 MB / 5000 行。仅支持物料、供应商和仓库。先预检，再确认执行。</div><div class="form-grid">${select('entity_type','导入实体',[['items','物料'],['suppliers','供应商'],['warehouses','仓库']],'items')}${select('mode','导入模式',[['CREATE','CREATE · 仅新增'],['UPDATE','UPDATE · 仅更新']],'CREATE')}</div><p style="margin-top:14px"><a id="template-download" href="/api/v1/import-template/items" class="text-link">${icon('download')} 下载 CSV 模板</a></p><label class="import-drop">选择 CSV 文件<input name="file" type="file" accept=".csv,text/csv" required></label><label>列映射（可选）<textarea name="mapping" placeholder='例如：{"物料编码":"code","物料名称":"name"}'>{}</textarea></label><p class="subtle" style="font-size:12px">左侧为 CSV 列名，右侧为模板字段名。使用模板时保留 {}。</p>`;formOpen('CSV 导入预检',html,async(d,f,key)=>{const form=new FormData(f);try{JSON.parse(form.get('mapping'))}catch{throw new Error('列映射必须是有效 JSON 对象')}const result=await api('import-jobs','POST',form,key);toast(result.data.status==='READY'?'预检通过，请确认执行':'发现逐行问题，请修正源文件后重新上传');await detail('import-jobs',result.data.id);await loadCurrentBehind()},'开始预检');$('[name=entity_type]').onchange=e=>$('#template-download').href='/api/v1/import-template/'+e.target.value}
async function loadCurrentBehind(){try{if(current==='dashboard')renderDashboard((await api('dashboard')).data);else await loadPage()}catch(e){toast(e.message,true)}}
async function command(action){const ctx=modalContext;if(!ctx)return;const {kind:k,record:x}=ctx;const run=async(route,payload={},key=modalKey)=>{await api(route,'POST',{expected_version:x.version,...payload},key);toast('操作成功');await detail(k,x.id);await loadCurrentBehind()};try{if(action.startsWith('transition:')){const target=action.split(':')[1];if(['BLOCKED','REJECTED'].includes(target))return reasonPrompt(target==='BLOCKED'?'设置阻塞原因':'填写拒收原因',reason=>run(k+'/'+x.id+'/transition',{target_status:target,reason}));return await run(k+'/'+x.id+'/transition',{target_status:target})}switch(action){case 'new-sample':return sampleForm(x);case 'retry-event':return run('events/'+x.id+'/retry');case 'edit-project':return projectForm(x);case 'edit-task':return taskForm(x);case 'edit-request':return requestForm(x);case 'members':return membersForm(x);case 'new-project-task':return taskForm(null,x.id);case 'new-order':return orderForm(x);case 'new-receipt':return receiptForm(x);case 'adjust':return adjustmentForm(x);case 'transfer-batch':return transferForm(x);case 'comment':await run('tasks/'+x.id+'/comments',{body:$('#comment-text').value});return;case 'approve':case 'reject':return reasonPrompt(action==='approve'?'批准采购申请':'驳回采购申请',reason=>run(k+'/'+x.id+'/decision',{decision:action==='approve'?'APPROVE':'REJECT',reason}));case 'submit':case 'withdraw':case 'confirm':case 'post':return run(k+'/'+x.id+'/'+action);case 'cancel':return confirmPrompt('确认取消单据','取消后该单据不能继续执行。',()=>run(k+'/'+x.id+'/cancel'));case 'reverse':case 'reverse-receipt':return reasonPrompt('冲销原始单据',async reason=>{await api('stock/movements/'+(action==='reverse-receipt'?x.movement_id:x.id)+'/reverse','POST',{reason},modalKey);toast('反向流水已生成，原始记录已保留');await detail(k,x.id);await loadCurrentBehind()});case 'post-issue':await api('stock/issues','POST',{draft_id:x.id,expected_version:x.version},modalKey);toast('领料已过账');await detail(k,x.id);await loadCurrentBehind();return;case 'withdraw-issue':return confirmPrompt('撤回领料需求','草稿会撤回，不影响库存。',async()=>{await api('stock/issues/drafts/'+x.id,'POST',{withdraw:true,expected_version:x.version},modalKey);await saved('领料需求已撤回')});case 'execute-import':return confirmPrompt('确认执行导入',`将执行 ${x.total_rows} 行${labels[x.mode]}操作。每行独立提交，成功行在重试时自动跳过。`,async()=>{const r=await api('import-jobs/'+x.id+'/execute','POST',{confirmed:true},modalKey);toast(r.data.status==='RUNNING'?'导入已加入后台队列，结果会自动刷新':`成功 ${r.data.success_rows} 行，失败 ${r.data.failed_rows} 行`);await detail(k,x.id);await loadCurrentBehind()})}}catch(e){const err=$('#command-error');if(err)err.textContent=e.message+(e.code?' · '+e.code:'');else toast(e.message,true)}}
function reasonPrompt(title,fn){formOpen(title,`<div class="form-grid">${textarea('reason','原因 / 处理意见','',true)}</div>`,async d=>fn(d.reason),'确认提交')}
function confirmPrompt(title,description,fn){formOpen(title,`<p>${esc(description)}</p>`,fn,'确认执行')}
async function action(name){try{switch(name){case 'create-lab-order':return labOrderForm();case 'create-sample':return sampleForm();case 'close':return closeDialog();case 'retry':case 'refresh':return navigate();case 'clear-filters':extra={};filter='';query='';paging.page=1;return loadPage();case 'create-master':return masterForm(kind);case 'create-project':return projectForm();case 'create-task':return taskForm();case 'create-request':return requestForm();case 'create-order':return orderForm();case 'create-receipt':return receiptForm();case 'create-issue':return issueForm();case 'create-transfer':return transferForm();case 'create-user':return userForm();case 'create-import':return importForm();case 'opening':return openingForm();case 'reconcile':{const d=(await api('stock/reconcile')).data;openDialog('库存台账核对',`<div class="dialog-content"><div class="reconcile-result">${d.differences.length?`发现 ${d.differences.length} 项余额与流水差异，请人工复核。`:'核对通过：所有批次仓库余额与已过账流水合计一致。'}</div>${d.differences.length?`<pre class="detail-json">${esc(JSON.stringify(d.differences,null,2))}</pre>`:''}</div>`);return}case 'check-alerts':{const d=(await api('operations/check','POST',{})).data;toast(`告警检查完成，处理 ${d.processed} 个事件`);return navigate()}}}catch(e){toast(e.message,true)}}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a,[data-detail]');if(!target)return;if(target.dataset.action){e.preventDefault();await action(target.dataset.action).catch(err=>toast(err.message,true))}else if(target.dataset.detail){e.preventDefault();await detail(target.dataset.detail,target.dataset.id)}else if(target.dataset.command){e.preventDefault();if(target.disabled)return;target.disabled=true;try{await command(target.dataset.command)}catch(err){toast(err.message,true)}finally{if(target.isConnected)target.disabled=false}}else if(target.dataset.tab){go(current,target.dataset.tab)}else if(target.dataset.page){paging.page+=target.dataset.page==='next'?1:-1;loadPage().catch(e=>toast(e.message,true))}else if(target.dataset.batches){go('inventory','balances',{item_id:target.dataset.batches})}else if(target.dataset.read){try{await api('notifications/'+target.dataset.read+'/read','POST',{});await loadPage()}catch(e){toast(e.message,true)}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail][role=button]')){e.preventDefault();detail(e.target.dataset.detail,e.target.dataset.id)}});
$('#close-dialog').onclick=closeDialog;$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#top-date').textContent=new Date().toLocaleDateString('zh-CN',{timeZone:'America/New_York',year:'numeric',month:'long',day:'numeric',weekday:'long'});window.addEventListener('hashchange',navigate);
(async()=>{try{me=(await api('me')).data;await navigate()}catch(e){$('#main').innerHTML=`<div class="error-state">${esc(e.message)}</div>`}})();

async function labOrderForm(){const [tests,ps]=await Promise.all([refs('test-catalog'),refs('projects')]);formOpen('新建模拟检测单',`<div class="notice">仅用于模拟实验室样本流转，不生成诊断结论或接入真实患者信息。</div><div class="form-grid">${select('project_id','所属项目',options(ps),'',true,true)}${select('test_id','检测类型',tests.map(t=>[t.id,`${t.name} · ${labels[t.sample_type]}`]),'',true,true)}${select('task_id','关联任务',[],'',false,true)}</div>`,async(d,f,key)=>{await api('lab-orders','POST',d,key);await saved('模拟检测单已创建')});$('[name=project_id]').onchange=async e=>{if(!e.target.value)return;const p=(await api('projects/'+e.target.value)).data;$('[name=task_id]').innerHTML='<option value="">不指定</option>'+options(p.tasks).map(([id,n])=>`<option value="${id}">${esc(n)}</option>`).join('')}}
async function sampleForm(order=null){const [orders,whs]=await Promise.all([refs('lab-orders'),refs('warehouses')]);const open=order?[order]:orders.filter(x=>x.status==='OPEN');if(!open.length){toast('请先创建处于待处理状态的模拟检测单',true);return}formOpen('登记模拟样本',`<div class="form-grid">${select('order_id','检测单 / 样本类型',open.map(x=>[x.id,`${x.order_no} · ${x.test_name} · ${labels[x.sample_type]}`]),order?.id||'',true,true)}${field('barcode','模拟样本条码','','text',true,true)}${select('storage_warehouse_id','存储仓库',options(whs),'',false,true)}</div>`,async(d,f,key)=>{await api('samples','POST',d,key);await saved('模拟样本已登记')})}
